use split_decls_genesis :: ourprelude :: * ; types ! { #! [unstable (feature = "stdarch_loongarch" , issue = "117427")] #[doc = " 128-bit wide integer vector type, LoongArch-specific"] #[doc = ""] #[doc = " This type is the same as the `__m128i` type defined in `lsxintrin.h`,"] #[doc = " representing a 128-bit SIMD register. Usage of this type typically"] #[doc = " occurs in conjunction with the `lsx` and higher target features for"] #[doc = " LoongArch."] #[doc = ""] #[doc = " Internally this type may be viewed as:"] #[doc = ""] #[doc = " * `i8x16` - sixteen `i8` values packed together"] #[doc = " * `i16x8` - eight `i16` values packed together"] #[doc = " * `i32x4` - four `i32` values packed together"] #[doc = " * `i64x2` - two `i64` values packed together"] #[doc = ""] #[doc = " (as well as unsigned versions). Each intrinsic may interpret the"] #[doc = " internal bits differently, check the documentation of the intrinsic"] #[doc = " to see how it's being used."] #[doc = ""] #[doc = " The in-memory representation of this type is the same as the one of an"] #[doc = " equivalent array (i.e. the in-memory order of elements is the same, and"] #[doc = " there is no padding); however, the alignment is different and equal to"] #[doc = " the size of the type. Note that the ABI for function calls may *not* be"] #[doc = " the same."] #[doc = ""] #[doc = " Note that this means that an instance of `m128i` typically just means"] #[doc = " a \"bag of bits\" which is left up to interpretation at the point of use."] #[doc = ""] #[doc = " Most intrinsics using `m128i` are prefixed with `lsx_` and the integer"] #[doc = " types tend to correspond to suffixes like \"b\", \"h\", \"w\" or \"d\"."] pub struct m128i (2 x i64) ; #[doc = " 128-bit wide set of four `f32` values, LoongArch-specific"] #[doc = ""] #[doc = " This type is the same as the `__m128` type defined in `lsxintrin.h`,"] #[doc = " representing a 128-bit SIMD register which internally consists of"] #[doc = " four packed `f32` instances. Usage of this type typically occurs in"] #[doc = " conjunction with the `lsx` and higher target features for LoongArch."] #[doc = ""] #[doc = " Note that unlike `m128i`, the integer version of the 128-bit registers,"] #[doc = " this `m128` type has *one* interpretation. Each instance of `m128`"] #[doc = " corresponds to `f32x4`, or four `f32` values packed together."] #[doc = ""] #[doc = " The in-memory representation of this type is the same as the one of an"] #[doc = " equivalent array (i.e. the in-memory order of elements is the same, and"] #[doc = " there is no padding); however, the alignment is different and equal to"] #[doc = " the size of the type. Note that the ABI for function calls may *not* be"] #[doc = " the same."] #[doc = ""] #[doc = " Most intrinsics using `m128` are prefixed with `lsx_` and are suffixed"] #[doc = " with \"s\"."] pub struct m128 (4 x f32) ; #[doc = " 128-bit wide set of two `f64` values, LoongArch-specific"] #[doc = ""] #[doc = " This type is the same as the `__m128d` type defined in `lsxintrin.h`,"] #[doc = " representing a 128-bit SIMD register which internally consists of"] #[doc = " two packed `f64` instances. Usage of this type typically occurs in"] #[doc = " conjunction with the `lsx` and higher target features for LoongArch."] #[doc = ""] #[doc = " Note that unlike `m128i`, the integer version of the 128-bit registers,"] #[doc = " this `m128d` type has *one* interpretation. Each instance of `m128d`"] #[doc = " always corresponds to `f64x2`, or two `f64` values packed together."] #[doc = ""] #[doc = " The in-memory representation of this type is the same as the one of an"] #[doc = " equivalent array (i.e. the in-memory order of elements is the same, and"] #[doc = " there is no padding); however, the alignment is different and equal to"] #[doc = " the size of the type. Note that the ABI for function calls may *not* be"] #[doc = " the same."] #[doc = ""] #[doc = " Most intrinsics using `m128d` are prefixed with `lsx_` and are suffixed"] #[doc = " with \"d\". Not to be confused with \"d\" which is used for `m128i`."] pub struct m128d (2 x f64) ; } #[allow (non_camel_case_types)] #[repr (simd)] pub (crate) struct __v16i8 ([i8 ; 16]) ; #[allow (non_camel_case_types)] #[repr (simd)] pub (crate) struct __v8i16 ([i16 ; 8]) ; #[allow (non_camel_case_types)] #[repr (simd)] pub (crate) struct __v4i32 ([i32 ; 4]) ; #[allow (non_camel_case_types)] #[repr (simd)] pub (crate) struct __v2i64 ([i64 ; 2]) ; #[allow (non_camel_case_types)] #[repr (simd)] pub (crate) struct __v16u8 ([u8 ; 16]) ; #[allow (non_camel_case_types)] #[repr (simd)] pub (crate) struct __v8u16 ([u16 ; 8]) ; #[allow (non_camel_case_types)] #[repr (simd)] pub (crate) struct __v4u32 ([u32 ; 4]) ; #[allow (non_camel_case_types)] #[repr (simd)] pub (crate) struct __v2u64 ([u64 ; 2]) ; #[allow (non_camel_case_types)] #[repr (simd)] pub (crate) struct __v4f32 ([f32 ; 4]) ; #[allow (non_camel_case_types)] #[repr (simd)] pub (crate) struct __v2f64 ([f64 ; 2]) ; #[allow (non_camel_case_types)] #[unstable (feature = "stdarch_loongarch" , issue = "117427")] pub type v16i8 = m128i ; #[allow (non_camel_case_types)] #[unstable (feature = "stdarch_loongarch" , issue = "117427")] pub type v8i16 = m128i ; #[allow (non_camel_case_types)] #[unstable (feature = "stdarch_loongarch" , issue = "117427")] pub type v4i32 = m128i ; #[allow (non_camel_case_types)] #[unstable (feature = "stdarch_loongarch" , issue = "117427")] pub type v2i64 = m128i ; #[allow (non_camel_case_types)] #[unstable (feature = "stdarch_loongarch" , issue = "117427")] pub type v16u8 = m128i ; #[allow (non_camel_case_types)] #[unstable (feature = "stdarch_loongarch" , issue = "117427")] pub type v8u16 = m128i ; #[allow (non_camel_case_types)] #[unstable (feature = "stdarch_loongarch" , issue = "117427")] pub type v4u32 = m128i ; #[allow (non_camel_case_types)] #[unstable (feature = "stdarch_loongarch" , issue = "117427")] pub type v2u64 = m128i ; #[allow (non_camel_case_types)] #[unstable (feature = "stdarch_loongarch" , issue = "117427")] pub type v4f32 = m128 ; #[allow (non_camel_case_types)] #[unstable (feature = "stdarch_loongarch" , issue = "117427")] pub type v2f64 = m128d ;